def flatten(d: dict) -> dict:
    """
    Flattens one level of nested dicts, joining keys with a dot.

    Examples:
        flatten({"a": {"b": 1}})  -> {"a.b": 1}
        flatten({"c": 2})         -> {"c": 2}
        flatten({"x": 5, "y": {"z": 6}}) -> {"x": 5, "y.z": 6}
    """
    result = {}
    for k, v in d.items():
        if isinstance(v, dict):
            # Flatten the nested dictionary one level deep
            for inner_k, inner_v in v.items():
                new_key = f"{k}.{inner_k}"
                result[new_key] = inner_v
        else:
            # Non-dict values are added directly
            result[k] = v
    return result
