def dedupe(rows: list[dict], key: str) -> list[dict]:
    seen_keys = set()
    result = []
    for row in rows:
        if key not in row or row[key] not in seen_keys:
            result.append(row)
            if key in row:
                seen_keys.add(row[key])
    return result
