def parse_money(s: str) -> float | None:
    """
    Turns strings like "$1,234.50" or "1234.5" into a number.

    Strips a leading $ and thousands separators (commas), 
    and returns None for anything that cannot be parsed (including "" and "n/a").
    """
    if not s:
        return None

    s_cleaned = s.strip()

    # Check for common non-parsable strings first
    if s_cleaned.lower() in ("n/a", ""):
        return None

    # Remove leading '$' if present and then remove all commas
    if s_cleaned.startswith('$'):
        s_cleaned = s_cleaned[1:]

    s_no_commas = s_cleaned.replace(",", "")

    try:
        return float(s_no_commas)
    except ValueError:
        # If conversion fails after cleaning, it's unparsable
        return None
